test('actual upstream graph rejects a new producer with an old consumer and wrong extra-role identity',()=>{
 const f=readySarifFixture(),p=f.make(),bundles=REQUIRED_PHASE_IDS.filter(id=>!id.startsWith('codeql-')).map(id=>bundle(p,id)),roles=linkFixtureBundles(p,bundles),proofs=bundles.map(b=>verifyOfficialPhase({plan:p,...b})),roleProofs=roles.map(b=>verifyOfficialPhase({plan:p,...b}));assert.equal(verifyUpstreamCoverage({plan:p,proofs,roleProofs}).length,1);assert.throws(()=>verifyUpstreamCoverage({plan:p,proofs,roleProofs:[]}),/extra artifact/);
 const stale=structuredClone(bundles.find(b=>b.phaseId==='backend-scan'));changedProof(stale,r=>{r.outputs.upstream[0].proofSHA256='0'.repeat(64);});const bad=verifyOfficialPhase({plan:p,...stale});assert.throws(()=>verifyUpstreamCoverage({plan:p,proofs:proofs.map(x=>x.phaseId===bad.phaseId?bad:x),roleProofs}),/different producer/);
 const forged=structuredClone(roles[0]);forged.expected.artifactId='3998';forged.artifact.id=3998;forged.artifactValidation.artifact.id=3998;const different=verifyOfficialPhase({plan:p,...forged});assert.throws(()=>verifyUpstreamCoverage({plan:p,proofs,roleProofs:[different]}));
});
test('aggregate standard proof stages through the actual artifact verifier without attempt type drift',async()=>{
 const {mkdtempSync,mkdirSync,rmSync}=await import('node:fs');const {tmpdir}=await import('node:os');const {join}=await import('node:path');const {writeAggregate}=await import('./pr356-admission.mjs');const {stageArtifact}=await import('./pr356-artifacts.mjs');const temporary=mkdtempSync(join(tmpdir(),'pr356-aggregate-control-'));
 try{const p=fixture().make(),out=join(temporary,'out');mkdirSync(out);const env={GITHUB_ACTIONS:'true',GITHUB_REPOSITORY:REPOSITORY,GITHUB_RUN_ID:'1001',GITHUB_RUN_ATTEMPT:'2',GITHUB_SHA:H,RUNNER_TEMP:temporary};const result=writeAggregate({plan:p,role:'qualification-result',out,payloadName:'qualification.json',payload:{kind:'synthetic-control-fixture-only',releaseAuthorized:false},startedAt:new Date().toISOString(),env,events:['actual synthetic aggregation fixture']});assert.equal(typeof result.proof.source.runId,'string');assert.equal(typeof result.proof.source.producerAttempt,'number');const stage=await stageArtifact({role:'qualification-result',spec:aggregateSpec(p,'qualification-result'),directory:out,destination:join(temporary,'stage'),env,readHead:()=>H});assert.equal(stage.qualificationClaim,false);assert.equal(stage.source.producerAttempt,2);assert.equal(stage.payloadFiles['aggregation.log'].sha256,result.proof.command.logSHA256);assert(stage.payloadFiles['qualification.json']);}
 finally{rmSync(temporary,{recursive:true,force:true});}
});
test('observe reports complete pending definitions without admitting or executing, while PR admission is manual-only',()=>{
 const f=fixture();for(const p of f.acceptance.phases)p.state='pending';for(const e of f.acceptance.evidence)e.state='pending';f.context.phase='observe';f.context.event='pull_request';const observed=createPr356Plan({binding:f.binding,acceptance:f.acceptance,entries:f.entries,base:B,head:M,context:f.context,read:f.read});assert.equal(observed.phase,'observe');assert.equal(observed.head,H);assert.equal(observed.checkout,M);assert.equal(observed.qualificationOnly,true);assert.equal(compactPlan(observed).requiredPhaseIds.length,16);assert.throws(()=>createMergeAdmission({plan:observed,qualification:{}}));const a=fixture('admit');a.context.event='pull_request';assert.throws(()=>createPr356Plan({binding:a.binding,acceptance:a.acceptance,entries:a.entries,base:B,head:M,context:a.context,read:a.read}),/manual-only/);
});

// A new input: a complete analysis with a nonempty result set. Existing green
// zero-result/full-chain contracts are deliberately not rerun for this change.
test('two-stage nonempty SARIF remains pending in immutable Q, requires exact admit review, and stages a numeric-attempt aggregate',async()=>{
 const {sarifIdentity}=await import('./pr356-sarif.mjs');const {verifyOfficialQualification,verifyOfficialAdmission,writeAggregate}=await import('./pr356-admission.mjs');const {stageArtifact}=await import('./pr356-artifacts.mjs');const {mkdtempSync,mkdirSync,rmSync}=await import('node:fs');const {tmpdir}=await import('node:os');const {join}=await import('node:path');
 const prepared=phase=>{const f=readySarifFixture(phase),document={schemaVersion:1,id:'nonempty-synthetic-review-policy-only',allowedDispositions:['fixture-reviewed']};f.acceptance.sarifPolicy={state:'fixed',document,sha256:canonicalSHA256(document)};return f;};
 const f=prepared('qualify'),p=f.make(),bundles=REQUIRED_PHASE_IDS.map(id=>bundle(p,id)),sarifArtifacts={};for(const b of bundles)if(b.phaseId.startsWith('codeql-'))sarifArtifacts[b.phaseId]=addSarif(p,b,{finding:b.phaseId==='codeql-javascript-typescript'}).finish(sarifIdentity);
 const roleBundles=linkFixtureBundles(p,bundles),roleProofs=roleBundles.map(b=>verifyOfficialPhase({plan:p,...b})),history=verifyHistoricalEvidence({plan:p,records:f.records(),read:f.read}),proofs=bundles.map(b=>verifyOfficialPhase({plan:p,...b}));const q=verifyQualification({plan:p,proofs,historicalEvidence:history,sarifArtifacts,readGitBytes:()=>Buffer.from('synthetic source bytes'),roleProofs});
 const summary=q.sarif.find(s=>s.phaseId==='codeql-javascript-typescript');assert.equal(summary.findings.length,1);assert(q.sarif.every(s=>s.status==='analysis-complete'&&s.disposition==='pending'));assert.equal(q.qualificationOnly,true);assert.equal(q.releaseAuthorized,false);const rawQ=Buffer.from(JSON.stringify(q));
 const af=prepared('admit'),ap=af.make(),qBundle=aggregateBundle(ap,'qualification-result',rawQ);const officialQ=verifyOfficialQualification({plan:ap,...qBundle,receiptBytes:rawQ,phaseBundles:bundles,roleBundles,historicalRecords:af.records(),read:af.read,readGitBytes:()=>Buffer.from('synthetic source bytes'),sarifArtifacts});
 assert.throws(()=>createMergeAdmission({plan:ap,qualification:officialQ}),/FINDINGS_UNREVIEWED/);const target={sourceHead:H,sourceTree:T,language:summary.language,sarifSHA256:summary.sarifSHA256,queryPackSHA256:summary.queryPackSHA256,resultSetSHA256:summary.resultSetSHA256,policySHA256:summary.policySHA256};const review={schemaVersion:1,reviewer:'synthetic controller fixture only',reviewedAt:'2026-10-26T12:00:00Z',target,findings:summary.findings.map(s=>({findingId:s.findingId,resultSHA256:s.resultSHA256,disposition:'fixture-reviewed',rationale:'Synthetic expected review; no real finding or human approval is claimed'}))};
 for(const mutate of [r=>r.target.sourceHead=B,r=>r.target.sarifSHA256='0'.repeat(64),r=>r.target.policySHA256='0'.repeat(64),r=>r.findings=[],r=>r.findings.push(r.findings[0]),r=>r.findings[0].resultSHA256='0'.repeat(64),r=>r.findings[0].disposition='unapproved-value']){const bad=structuredClone(review);mutate(bad);assert.throws(()=>createMergeAdmission({plan:ap,qualification:officialQ,reviews:{'codeql-javascript-typescript':bad}}),/REVIEW_TARGET|REVIEW_COVERAGE|FINDING_DISPOSITION_REQUIRED/);}
 const reviews={'codeql-javascript-typescript':review},admission=createMergeAdmission({plan:ap,qualification:officialQ,reviews});assert(admission.sarif.every(s=>s.status==='accepted'));assert.deepEqual(admission.sarifReviews,reviews);assert.equal(admission.qualificationSHA256,q.receiptSHA256);assert.equal(JSON.stringify(q),rawQ.toString(),'Disposition must not relabel or rewrite original Q');assert.equal(admission.reviewAuthentication,'not-established');assert.equal(admission.releaseAuthorized,false);
 const mf=prepared('postmerge'),mp=mf.make(),rawA=Buffer.from(JSON.stringify(admission)),aBundle=aggregateBundle(mp,'merge-admission',rawA,'1002'),official=verifyOfficialAdmission({plan:mp,...aBundle,receiptBytes:rawA});assert.equal(verifyMainReuse({plan:mp,officialAdmission:official,qualification:officialQ}).checksRepeated,false);
 const temporary=mkdtempSync(join(tmpdir(),'pr356-nonempty-aggregate-'));try{const out=join(temporary,'out');mkdirSync(out);const env={GITHUB_ACTIONS:'true',GITHUB_REPOSITORY:REPOSITORY,GITHUB_RUN_ID:'1001',GITHUB_RUN_ATTEMPT:'2',GITHUB_SHA:H,RUNNER_TEMP:temporary},result=writeAggregate({plan:p,role:'qualification-result',out,payloadName:'qualification.json',payload:q,startedAt:new Date().toISOString(),env,events:['synthetic nonempty SARIF pending qualification']});assert.equal(typeof result.proof.source.producerAttempt,'number');assert.equal(result.proof.source.producerAttempt,2);const staged=await stageArtifact({role:'qualification-result',spec:aggregateSpec(p,'qualification-result'),directory:out,destination:join(temporary,'stage'),env,readHead:()=>H});assert.equal(staged.source.producerAttempt,2);assert.equal(staged.qualificationClaim,false);assert.equal(staged.payloadFiles['qualification.json'].sha256,sha256(readFileSync(join(out,'qualification.json'))));}finally{rmSync(temporary,{recursive:true,force:true});}
});
